PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE schools (
            school_id TEXT PRIMARY KEY,
            school_name TEXT NOT NULL,
            district TEXT NOT NULL,
            state TEXT NOT NULL,
            school_type TEXT NOT NULL
        , address TEXT, established_year INTEGER, description TEXT, public_phone TEXT, website TEXT, facilities_json TEXT NOT NULL DEFAULT '[]', logo_url TEXT, cover_image_url TEXT, email TEXT, affiliation TEXT, recognition TEXT, campus_name TEXT, is_parent_group INTEGER DEFAULT 0, map_url TEXT, about_json TEXT, facilities_details_json TEXT, hostel_details_json TEXT, transport_details_json TEXT, admissions_details_json TEXT, category TEXT, latitude REAL, longitude REAL);
CREATE TABLE students (
            student_id TEXT PRIMARY KEY,
            student_name TEXT NOT NULL,
            school_id TEXT NOT NULL,
            standard INTEGER NOT NULL,
            section TEXT NOT NULL,
            age INTEGER NOT NULL, permanent_student_id TEXT, first_language TEXT, date_of_birth TEXT, gender TEXT, admission_date TEXT, enrollment_status TEXT NOT NULL DEFAULT 'active',
            FOREIGN KEY (school_id)
                REFERENCES schools(school_id)
        );
CREATE TABLE guardians (
                    guardian_id TEXT PRIMARY KEY,
                    user_id TEXT UNIQUE,
                    full_name TEXT NOT NULL,
                    relationship TEXT NOT NULL,
                    phone TEXT NOT NULL,
                    email TEXT,
                    address TEXT,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (user_id) REFERENCES users(user_id)
                );
CREATE TABLE student_guardians (
                    student_guardian_id TEXT PRIMARY KEY,
                    permanent_student_id TEXT NOT NULL,
                    guardian_id TEXT NOT NULL,
                    can_view_records INTEGER NOT NULL DEFAULT 1,
                    can_request_updates INTEGER NOT NULL DEFAULT 1,
                    is_verified INTEGER NOT NULL DEFAULT 0,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE (permanent_student_id, guardian_id),
                    FOREIGN KEY (permanent_student_id)
                        REFERENCES students(permanent_student_id),
                    FOREIGN KEY (guardian_id) REFERENCES guardians(guardian_id)
                );
CREATE TABLE enrollments (
                    enrollment_id TEXT PRIMARY KEY,
                    permanent_student_id TEXT NOT NULL,
                    school_id TEXT NOT NULL,
                    academic_year TEXT NOT NULL,
                    standard INTEGER NOT NULL CHECK (standard BETWEEN 1 AND 12),
                    section TEXT NOT NULL CHECK (section IN ('A', 'B', 'C')),
                    first_language TEXT NOT NULL CHECK (
                        first_language IN ('Kannada', 'Hindi', 'Sanskrit')
                    ),
                    stream TEXT,
                    subject_combination TEXT,
                    admission_date TEXT,
                    leaving_date TEXT,
                    enrollment_status TEXT NOT NULL DEFAULT 'active'
                        CHECK (enrollment_status IN (
                            'active', 'completed', 'transferred', 'withdrawn'
                        )),
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (permanent_student_id)
                        REFERENCES students(permanent_student_id),
                    FOREIGN KEY (school_id) REFERENCES schools(school_id),
                    UNIQUE (permanent_student_id, school_id, academic_year)
                );
CREATE TABLE academic_results (
                    result_id TEXT PRIMARY KEY,
                    enrollment_id TEXT NOT NULL,
                    subject_name TEXT NOT NULL,
                    exam_name TEXT NOT NULL,
                    marks_obtained REAL NOT NULL CHECK (marks_obtained >= 0),
                    maximum_marks REAL NOT NULL CHECK (maximum_marks > 0),
                    academic_year TEXT NOT NULL,
                    exam_date TEXT,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, permanent_student_id TEXT, exam_id TEXT, grade TEXT, percentage REAL, recorded_by_user_id TEXT, updated_at TEXT,
                    FOREIGN KEY (enrollment_id)
                        REFERENCES enrollments(enrollment_id)
                );
CREATE TABLE student_documents (
                    document_id TEXT PRIMARY KEY,
                    permanent_student_id TEXT NOT NULL,
                    enrollment_id TEXT,
                    document_type TEXT NOT NULL,
                    file_name TEXT NOT NULL,
                    private_storage_key TEXT NOT NULL,
                    uploaded_by_user_id TEXT,
                    verified_by_user_id TEXT,
                    verification_status TEXT NOT NULL DEFAULT 'pending'
                        CHECK (verification_status IN (
                            'pending', 'verified', 'rejected'
                        )),
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (permanent_student_id)
                        REFERENCES students(permanent_student_id),
                    FOREIGN KEY (enrollment_id)
                        REFERENCES enrollments(enrollment_id),
                    FOREIGN KEY (uploaded_by_user_id)
                        REFERENCES users(user_id),
                    FOREIGN KEY (verified_by_user_id)
                        REFERENCES users(user_id)
                );
CREATE TABLE fees (
                    fee_id TEXT PRIMARY KEY,
                    permanent_student_id TEXT NOT NULL,
                    school_id TEXT NOT NULL,
                    academic_year TEXT NOT NULL,
                    fee_type TEXT NOT NULL,
                    amount_due REAL NOT NULL CHECK (amount_due >= 0),
                    amount_paid REAL NOT NULL DEFAULT 0 CHECK (amount_paid >= 0),
                    due_date TEXT,
                    payment_status TEXT NOT NULL DEFAULT 'pending'
                        CHECK (payment_status IN (
                            'pending', 'partially_paid', 'paid', 'waived'
                        )),
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (permanent_student_id)
                        REFERENCES students(permanent_student_id),
                    FOREIGN KEY (school_id) REFERENCES schools(school_id)
                );
CREATE TABLE scholarships (
                    scholarship_id TEXT PRIMARY KEY,
                    permanent_student_id TEXT NOT NULL,
                    scholarship_name TEXT NOT NULL,
                    eligibility_status TEXT NOT NULL DEFAULT 'not_assessed'
                        CHECK (eligibility_status IN (
                            'not_assessed', 'eligible', 'ineligible', 'needs_review'
                        )),
                    application_status TEXT NOT NULL DEFAULT 'not_applied'
                        CHECK (application_status IN (
                            'not_applied', 'submitted', 'under_review',
                            'approved', 'rejected'
                        )),
                    academic_year TEXT NOT NULL,
                    notes TEXT,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (permanent_student_id)
                        REFERENCES students(permanent_student_id)
                );
CREATE TABLE update_requests (
                    request_id TEXT PRIMARY KEY,
                    permanent_student_id TEXT NOT NULL,
                    guardian_id TEXT NOT NULL,
                    request_type TEXT NOT NULL CHECK (
                        request_type IN ('request_change', 'report_change')
                    ),
                    field_name TEXT NOT NULL,
                    old_value TEXT,
                    proposed_value TEXT NOT NULL,
                    reason TEXT,
                    supporting_document_id TEXT,
                    status TEXT NOT NULL DEFAULT 'pending'
                        CHECK (status IN (
                            'pending', 'approved', 'rejected', 'cancelled'
                        )),
                    reviewed_by_user_id TEXT,
                    review_comment TEXT,
                    submitted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    reviewed_at TEXT,
                    FOREIGN KEY (permanent_student_id)
                        REFERENCES students(permanent_student_id),
                    FOREIGN KEY (guardian_id) REFERENCES guardians(guardian_id),
                    FOREIGN KEY (supporting_document_id)
                        REFERENCES student_documents(document_id),
                    FOREIGN KEY (reviewed_by_user_id)
                        REFERENCES users(user_id)
                );
CREATE TABLE school_transfers (
                    transfer_id TEXT PRIMARY KEY,
                    permanent_student_id TEXT NOT NULL,
                    previous_enrollment_id TEXT,
                    new_enrollment_id TEXT,
                    requested_by_guardian_id TEXT,
                    status TEXT NOT NULL DEFAULT 'pending'
                        CHECK (status IN (
                            'pending', 'approved', 'rejected', 'completed'
                        )),
                    reason TEXT,
                    requested_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    reviewed_by_user_id TEXT,
                    reviewed_at TEXT,
                    FOREIGN KEY (permanent_student_id)
                        REFERENCES students(permanent_student_id),
                    FOREIGN KEY (previous_enrollment_id)
                        REFERENCES enrollments(enrollment_id),
                    FOREIGN KEY (new_enrollment_id)
                        REFERENCES enrollments(enrollment_id),
                    FOREIGN KEY (requested_by_guardian_id)
                        REFERENCES guardians(guardian_id),
                    FOREIGN KEY (reviewed_by_user_id)
                        REFERENCES users(user_id)
                );
CREATE TABLE school_programs (
                    program_id TEXT PRIMARY KEY,
                    school_id TEXT NOT NULL,
                    standard INTEGER NOT NULL CHECK (standard BETWEEN 1 AND 12),
                    section TEXT CHECK (section IN ('A', 'B', 'C')),
                    first_language TEXT CHECK (
                        first_language IN ('Kannada', 'Hindi', 'Sanskrit')
                    ),
                    stream TEXT,
                    subject_combination TEXT,
                    is_available INTEGER NOT NULL DEFAULT 1,
                    FOREIGN KEY (school_id) REFERENCES schools(school_id)
                );
CREATE TABLE school_achievements (
                    achievement_id TEXT PRIMARY KEY,
                    school_id TEXT NOT NULL,
                    title TEXT NOT NULL,
                    description TEXT,
                    achievement_date TEXT,
                    public_document_url TEXT,
                    is_published INTEGER NOT NULL DEFAULT 0, year INTEGER, award_level TEXT DEFAULT 'State', issuing_authority TEXT, verification_status TEXT DEFAULT 'verified',
                    FOREIGN KEY (school_id) REFERENCES schools(school_id)
                );
CREATE TABLE school_change_log (
                    log_id TEXT PRIMARY KEY,
                    school_id TEXT NOT NULL,
                    permanent_student_id TEXT NOT NULL,
                    field_name TEXT NOT NULL,
                    old_value TEXT,
                    new_value TEXT,
                    changed_by_user_id TEXT,
                    change_reason TEXT,
                    changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (school_id) REFERENCES schools(school_id),
                    FOREIGN KEY (permanent_student_id)
                        REFERENCES students(permanent_student_id),
                    FOREIGN KEY (changed_by_user_id)
                        REFERENCES users(user_id)
                );
CREATE TABLE linking_requests (
                    request_id TEXT PRIMARY KEY,
                    parent_user_id TEXT NOT NULL,
                    school_id TEXT NOT NULL,
                    student_ref TEXT NOT NULL,
                    relationship_type TEXT NOT NULL,
                    verification_doc_id TEXT,
                    additional_notes TEXT,
                    request_status TEXT NOT NULL DEFAULT 'pending'
                        CHECK (request_status IN (
                            'pending', 'approved', 'rejected', 'cancelled'
                        )),
                    reviewer_user_id TEXT,
                    reviewer_comment TEXT,
                    permanent_student_id TEXT,
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    reviewed_at TEXT,
                    CHECK (
                        request_status != 'approved'
                        OR permanent_student_id IS NOT NULL
                    ),
                    FOREIGN KEY (parent_user_id) REFERENCES users(user_id),
                    FOREIGN KEY (school_id) REFERENCES schools(school_id),
                    FOREIGN KEY (reviewer_user_id) REFERENCES users(user_id),
                    FOREIGN KEY (permanent_student_id)
                        REFERENCES students(permanent_student_id)
                );
CREATE TABLE audit_logs (
                    audit_id TEXT PRIMARY KEY,
                    actor_user_id TEXT,
                    actor_role TEXT,
                    action TEXT NOT NULL,
                    entity_type TEXT NOT NULL,
                    entity_id TEXT,
                    school_id TEXT,
                    ip_address TEXT,
                    metadata_json TEXT NOT NULL DEFAULT '{}',
                    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (actor_user_id) REFERENCES users(user_id),
                    FOREIGN KEY (school_id) REFERENCES schools(school_id)
                );
CREATE TABLE collegiate_enrollments (
    enrollment_id TEXT PRIMARY KEY,
    permanent_student_id TEXT NOT NULL,
    institution_id TEXT NOT NULL,
    program_id TEXT NOT NULL,
    academic_year TEXT NOT NULL,
    current_year_or_term INTEGER NOT NULL CHECK (current_year_or_term >= 1),
    section TEXT NOT NULL DEFAULT 'A',
    enrollment_status TEXT NOT NULL DEFAULT 'active' CHECK (
        enrollment_status IN ('active', 'completed', 'transferred', 'withdrawn')
    ),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (permanent_student_id) REFERENCES students(permanent_student_id),
    FOREIGN KEY (institution_id) REFERENCES schools(school_id),
    FOREIGN KEY (program_id) REFERENCES academic_programs(program_id),
    UNIQUE (permanent_student_id, program_id, academic_year)
);
CREATE TABLE program_sections (
    section_id TEXT PRIMARY KEY,
    institution_id TEXT NOT NULL,
    program_id TEXT NOT NULL,
    academic_year TEXT NOT NULL,
    term_or_year INTEGER NOT NULL DEFAULT 1,
    semester INTEGER,
    section_name TEXT NOT NULL,
    capacity INTEGER NOT NULL DEFAULT 60,
    current_strength INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (institution_id) REFERENCES schools(school_id),
    FOREIGN KEY (program_id) REFERENCES academic_programs(program_id),
    UNIQUE (institution_id, program_id, academic_year, term_or_year, section_name)
);
CREATE TABLE institution_divisions (
        division_id VARCHAR(50) PRIMARY KEY,
        parent_institution_id VARCHAR(20) NOT NULL,
        division_name VARCHAR(255) NOT NULL,
        division_type VARCHAR(100) NOT NULL,
        campus_location VARCHAR(255) NOT NULL,
        head_of_division VARCHAR(100),
        contact_phone VARCHAR(50),
        contact_email VARCHAR(100),
        facilities_summary TEXT,
        description TEXT,
        display_order INTEGER DEFAULT 1,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (parent_institution_id) REFERENCES schools(school_id) ON DELETE CASCADE
    );
CREATE TABLE admission_applications (
        application_id VARCHAR(50) PRIMARY KEY,
        institution_id VARCHAR(20) NOT NULL,
        division_id VARCHAR(50) DEFAULT NULL,
        parent_user_id VARCHAR(50) DEFAULT NULL,
        applicant_name VARCHAR(150) NOT NULL,
        parent_name VARCHAR(150) NOT NULL,
        parent_phone VARCHAR(20) NOT NULL,
        parent_email VARCHAR(100),
        residential_address TEXT NOT NULL,
        academic_year VARCHAR(20) NOT NULL,
        education_level VARCHAR(50) NOT NULL,
        requested_standard INTEGER DEFAULT NULL,
        requested_program_id VARCHAR(50) DEFAULT NULL,
        first_language_preference VARCHAR(50) DEFAULT NULL,
        stream_preference VARCHAR(50) DEFAULT NULL,
        combination_code VARCHAR(20) DEFAULT NULL,
        status VARCHAR(50) NOT NULL DEFAULT 'submitted',
        reviewer_user_id VARCHAR(50) DEFAULT NULL,
        rejection_reason TEXT DEFAULT NULL,
        rejection_explanation TEXT DEFAULT NULL,
        institution_contact_phone VARCHAR(50) DEFAULT NULL,
        clarification_request TEXT DEFAULT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, second_language_preference VARCHAR(50) DEFAULT NULL, enrolled_student_id TEXT, enrolled_at TEXT,
        FOREIGN KEY (institution_id) REFERENCES schools(school_id) ON DELETE RESTRICT,
        FOREIGN KEY (requested_program_id) REFERENCES academic_programs(program_id) ON DELETE RESTRICT
    );
CREATE TABLE admission_detailed_submissions (
        submission_id VARCHAR(50) PRIMARY KEY,
        application_id VARCHAR(50) UNIQUE NOT NULL,
        date_of_birth DATE,
        gender VARCHAR(20),
        blood_group VARCHAR(10),
        previous_institution_name VARCHAR(255),
        previous_institution_location VARCHAR(255),
        previous_standard_or_degree VARCHAR(100),
        previous_board VARCHAR(100),
        previous_marks_percentage REAL,
        emergency_contact_name VARCHAR(100),
        emergency_contact_phone VARCHAR(20),
        custom_fields_json TEXT,
        status VARCHAR(50) NOT NULL DEFAULT 'submitted',
        submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (application_id) REFERENCES admission_applications(application_id) ON DELETE CASCADE
    );
CREATE TABLE admission_documents (
        document_id VARCHAR(50) PRIMARY KEY,
        application_id VARCHAR(50) NOT NULL,
        document_type VARCHAR(100) NOT NULL,
        file_name VARCHAR(255) NOT NULL,
        file_path VARCHAR(500) NOT NULL,
        file_size_bytes INTEGER NOT NULL,
        mime_type VARCHAR(100) NOT NULL,
        verification_status VARCHAR(50) DEFAULT 'pending',
        uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, verified_by_user_id VARCHAR(50) DEFAULT NULL, verified_at TIMESTAMP DEFAULT NULL, verification_notes TEXT DEFAULT NULL,
        FOREIGN KEY (application_id) REFERENCES admission_applications(application_id) ON DELETE CASCADE
    );
CREATE TABLE portal_notifications (
        notification_id VARCHAR(50) PRIMARY KEY,
        recipient_user_id VARCHAR(50) DEFAULT NULL,
        recipient_role VARCHAR(50) DEFAULT NULL,
        institution_id VARCHAR(20) DEFAULT NULL,
        application_id VARCHAR(50) DEFAULT NULL,
        title VARCHAR(255) NOT NULL,
        message TEXT NOT NULL,
        action_url VARCHAR(255),
        is_read INTEGER DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    , category VARCHAR(50) DEFAULT 'general', priority VARCHAR(20) DEFAULT 'normal', channel VARCHAR(20) DEFAULT 'in_app', delivery_status VARCHAR(30) DEFAULT 'delivered', related_record_type VARCHAR(50), related_record_id VARCHAR(100), read_at TIMESTAMP, idempotency_key VARCHAR(150));
CREATE TABLE admission_status_history (
        history_id VARCHAR(50) PRIMARY KEY,
        application_id VARCHAR(50) NOT NULL,
        previous_status VARCHAR(50),
        new_status VARCHAR(50) NOT NULL,
        action_by_user_id VARCHAR(50) NOT NULL,
        action_note TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (application_id) REFERENCES admission_applications(application_id) ON DELETE CASCADE
    );
CREATE TABLE document_ocr_extractions (
    extraction_id TEXT PRIMARY KEY,
    document_id TEXT NOT NULL,
    application_id TEXT NOT NULL,
    raw_text TEXT NOT NULL,
    ocr_engine TEXT NOT NULL,
    average_confidence REAL NOT NULL,
    extracted_entities_json TEXT NOT NULL,
    match_status TEXT NOT NULL DEFAULT 'unreviewed',
    discrepancy_notes TEXT,
    extracted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (document_id) REFERENCES admission_documents(document_id),
    FOREIGN KEY (application_id) REFERENCES admission_applications(application_id)
);
CREATE TABLE user_institution_roles (
            id TEXT PRIMARY KEY,
            user_id TEXT NOT NULL,
            institution_id TEXT NOT NULL,
            role_id TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'active',
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            created_by TEXT,
            FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE,
            FOREIGN KEY (institution_id) REFERENCES schools(school_id) ON DELETE CASCADE
        );
CREATE TABLE invitation_tokens (
            token_id TEXT PRIMARY KEY,
            token_hash TEXT NOT NULL UNIQUE,
            user_id TEXT NOT NULL,
            institution_id TEXT NOT NULL,
            role_id TEXT NOT NULL,
            expires_at TIMESTAMP NOT NULL,
            is_used INTEGER DEFAULT 0,
            used_at TIMESTAMP,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            created_by TEXT,
            FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE,
            FOREIGN KEY (institution_id) REFERENCES schools(school_id) ON DELETE CASCADE
        );
CREATE TABLE password_reset_tokens (
            reset_id TEXT PRIMARY KEY,
            token_hash TEXT NOT NULL UNIQUE,
            user_id TEXT NOT NULL,
            expires_at TIMESTAMP NOT NULL,
            is_used INTEGER DEFAULT 0,
            used_at TIMESTAMP,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE
        );
CREATE TABLE IF NOT EXISTS "academic_programs" (
            program_id TEXT PRIMARY KEY,
            institution_id TEXT NOT NULL,
            education_level TEXT NOT NULL,
            program_name TEXT NOT NULL,
            degree_type TEXT NOT NULL DEFAULT 'None',
            discipline_or_stream TEXT,
            combination_code TEXT,
            faculty_name TEXT,
            department_name TEXT,
            duration_years INTEGER NOT NULL DEFAULT 1,
            is_active INTEGER NOT NULL DEFAULT 1,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (institution_id) REFERENCES schools(school_id)
        );
CREATE TABLE institution_staff_permissions (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    institution_id TEXT NOT NULL,
    role_id TEXT NOT NULL,
    can_view_applications INTEGER NOT NULL DEFAULT 0,
    can_review_details INTEGER NOT NULL DEFAULT 0,
    can_request_clarification INTEGER NOT NULL DEFAULT 0,
    can_recommend_decision INTEGER NOT NULL DEFAULT 0,
    can_approve_stage1 INTEGER NOT NULL DEFAULT 0,
    can_view_history INTEGER NOT NULL DEFAULT 0,
    can_manage_academics INTEGER NOT NULL DEFAULT 0,
    can_manage_students INTEGER NOT NULL DEFAULT 0,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    FOREIGN KEY (user_id) REFERENCES users(user_id),
    FOREIGN KEY (institution_id) REFERENCES schools(school_id)
);
CREATE TABLE staff_applications (
    application_id TEXT PRIMARY KEY,
    candidate_token TEXT UNIQUE NOT NULL,
    institution_id TEXT NOT NULL,
    candidate_email TEXT NOT NULL,
    candidate_name TEXT NOT NULL,
    candidate_phone TEXT,
    role_id TEXT NOT NULL DEFAULT 'school_staff',
    status TEXT NOT NULL DEFAULT 'invited',
    qualifications_json TEXT DEFAULT '[]',
    employment_details_json TEXT DEFAULT '{}',
    documents_json TEXT DEFAULT '[]',
    correction_notes TEXT,
    review_notes TEXT,
    created_by_user_id TEXT,
    reviewed_by_user_id TEXT,
    reviewed_at TIMESTAMP,
    activation_token TEXT UNIQUE,
    activation_expires_at TIMESTAMP,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (institution_id) REFERENCES schools(school_id) ON DELETE CASCADE,
    FOREIGN KEY (created_by_user_id) REFERENCES users(user_id) ON DELETE SET NULL,
    FOREIGN KEY (reviewed_by_user_id) REFERENCES users(user_id) ON DELETE SET NULL
);
CREATE TABLE IF NOT EXISTS "users" (
    user_id TEXT PRIMARY KEY,
    email TEXT UNIQUE,
    phone TEXT UNIQUE,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL CHECK (
        role IN ('parent', 'school_staff', 'school_admin', 'platform_admin', 'student')
    ),
    school_id TEXT,
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    full_name TEXT,
    status TEXT DEFAULT 'active',
    last_login TEXT,
    permanent_student_id TEXT,
    student_id TEXT, is_email_verified INTEGER NOT NULL DEFAULT 1,
    FOREIGN KEY (school_id) REFERENCES schools(school_id)
);
CREATE TABLE student_attendance (
            attendance_id TEXT PRIMARY KEY,
            institution_id TEXT NOT NULL,
            permanent_student_id TEXT NOT NULL,
            academic_year TEXT NOT NULL DEFAULT '2026-2027',
            attendance_date TEXT NOT NULL,
            status TEXT NOT NULL CHECK(status IN ('present', 'absent', 'leave')),
            subject_name TEXT,
            remarks TEXT,
            recorded_by_user_id TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (institution_id) REFERENCES schools(school_id),
            FOREIGN KEY (permanent_student_id) REFERENCES students(permanent_student_id),
            FOREIGN KEY (recorded_by_user_id) REFERENCES users(user_id)
        );
CREATE TABLE examinations (
            exam_id TEXT PRIMARY KEY,
            institution_id TEXT NOT NULL,
            academic_year TEXT NOT NULL DEFAULT '2026-2027',
            exam_name TEXT NOT NULL,
            standard_or_level TEXT NOT NULL,
            start_date TEXT,
            end_date TEXT,
            status TEXT NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled', 'ongoing', 'completed', 'cancelled')),
            description TEXT,
            created_by_user_id TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (institution_id) REFERENCES schools(school_id),
            FOREIGN KEY (created_by_user_id) REFERENCES users(user_id)
        );
CREATE TABLE academic_result_audits (
            audit_id TEXT PRIMARY KEY,
            result_id TEXT NOT NULL,
            previous_marks REAL,
            new_marks REAL,
            previous_max_marks REAL,
            new_max_marks REAL,
            reason_for_change TEXT NOT NULL,
            modified_by_user_id TEXT NOT NULL,
            modified_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (result_id) REFERENCES academic_results(result_id),
            FOREIGN KEY (modified_by_user_id) REFERENCES users(user_id)
        );
CREATE TABLE institution_announcements (
            announcement_id TEXT PRIMARY KEY,
            institution_id TEXT NOT NULL,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            target_audience TEXT NOT NULL DEFAULT 'all' CHECK(target_audience IN ('all', 'students', 'parents', 'staff')),
            published_date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            created_by_user_id TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (institution_id) REFERENCES schools(school_id),
            FOREIGN KEY (created_by_user_id) REFERENCES users(user_id)
        );
CREATE TABLE notification_preferences (
    preference_id VARCHAR(50) PRIMARY KEY,
    user_id VARCHAR(50) NOT NULL UNIQUE,
    academic_updates INTEGER DEFAULT 1,
    attendance_alerts INTEGER DEFAULT 1,
    examination_alerts INTEGER DEFAULT 1,
    admission_updates INTEGER DEFAULT 1,
    institution_announcements INTEGER DEFAULT 1,
    administrative_alerts INTEGER DEFAULT 1,
    email_enabled INTEGER DEFAULT 1,
    sms_enabled INTEGER DEFAULT 1,
    whatsapp_enabled INTEGER DEFAULT 0,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE notification_delivery_logs (
    log_id VARCHAR(50) PRIMARY KEY,
    notification_id VARCHAR(50) NOT NULL,
    channel VARCHAR(20) NOT NULL,
    recipient_destination VARCHAR(100),
    status VARCHAR(30) NOT NULL,
    error_message TEXT,
    retry_count INTEGER DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (notification_id) REFERENCES portal_notifications(notification_id)
);
CREATE TABLE platform_audit_logs (
        id TEXT PRIMARY KEY,
        event_type TEXT NOT NULL,
        event_category TEXT NOT NULL,
        institution_id TEXT,
        actor_user_id TEXT,
        actor_name TEXT,
        actor_role TEXT,
        entity_type TEXT NOT NULL,
        entity_id TEXT,
        action TEXT NOT NULL,
        old_values TEXT,
        new_values TEXT,
        remarks TEXT,
        request_id TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
CREATE TABLE phone_otps (
    otp_id TEXT PRIMARY KEY,
    phone TEXT NOT NULL,
    otp_hash TEXT NOT NULL,
    purpose TEXT NOT NULL,
    attempts INTEGER DEFAULT 0,
    max_attempts INTEGER DEFAULT 5,
    is_used INTEGER DEFAULT 0,
    expires_at TEXT NOT NULL,
    created_at TEXT NOT NULL,
    ip_address TEXT
);
CREATE TABLE email_otps (
                    otp_id TEXT PRIMARY KEY,
                    email TEXT NOT NULL,
                    otp_hash TEXT NOT NULL,
                    purpose TEXT NOT NULL,
                    attempts INTEGER DEFAULT 0,
                    max_attempts INTEGER DEFAULT 5,
                    is_used INTEGER DEFAULT 0,
                    expires_at TEXT NOT NULL,
                    created_at TEXT NOT NULL,
                    ip_address TEXT
                );
