INSERT INTO schools VALUES('SCH001','Government Model School','Bengaluru Urban','Karnataka','School','Near BBMP Office, Malleshwaram 18th Cross, Bengaluru, Karnataka 560003',1954,NULL,'+91-80-2334-1100','https://schooleducation.karnataka.gov.in','[]','https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Government_of_Karnataka_Logo.svg/300px-Government_of_Karnataka_Logo.svg.png','https://images.unsplash.com/photo-1580582932707-520aed937b7b?q=80&w=1200&auto=format&fit=crop','sch001.gms.blr@karnataka.gov.in','Karnataka School Examination and Assessment Board (KSEAB)','Department of School Education and Literacy, Government of Karnataka','Malleshwaram Heritage Complex',1,'https://maps.google.com/?q=Malleshwaram+Government+School+Bengaluru','{"introduction": "Government Model School, Malleshwaram, is a premier state government educational institution founded in 1954. Recognized as a PM SHRI Model School, it offers quality bilingual education (Kannada and English medium) from Standard 1 through Standard 10 with state-of-the-art smart classrooms and midday meal schemes.", "history": "Established post-independence to provide high quality, inclusive schooling to children of all backgrounds, the school has achieved consistent 100% pass results in SSLC board examinations for over two decades.", "vision": "To empower every child with foundational literacy, digital proficiency, and ethical values in an inclusive public school environment.", "mission": ["Deliver child-centric, joyful learning through Activity-Based Learning (Nali-Kali) and digital smartboards.", "Ensure 100% retention and zero dropout through holistic student welfare schemes.", "Nurture sporting, cultural, and scientific curiosity through clubs and state exhibitions."], "educational_philosophy": "Equitable and inclusive quality education adhering to the National Curriculum Framework (NCF) and Karnataka State Syllabus.", "teaching_methodology": "Nali-Kali methodology for primary classes (1-3), experiential science kits, bilingual textbooks, and interactive multimedia lessons.", "academic_environment": "Peaceful, tree-shaded campus with a dedicated playground, herb garden, computer lab, and activity rooms."}','{"classrooms": {"available": true, "count": 24, "description": "Well-ventilated classrooms with child-friendly desks, green boards, and 10 PM-SHRI smart interactive panels."}, "science_labs": {"available": true, "count": 2, "description": "Equipped general science and ATL (Atal Tinkering Lab) with robotics and sensor kits."}, "computer_labs": {"available": true, "count": 1, "description": "Cal-C computer laboratory with 30 networked desktops providing digital literacy training."}, "library": {"available": true, "details": "School library holding 8,500+ children''s storybooks, Kannada literature, and reference encyclopedias."}, "digital_learning": {"available": true, "details": "Smart class setup powered by Karnataka DSERT digital curriculum with animated lessons."}, "sports": {"available": true, "details": "Spacious sports ground with kho-kho, kabaddi, volleyball courts, and athletic running tracks."}, "auditorium": {"available": true, "count": 1, "details": "School multipurpose community hall with stage and audio system seating 350 pupils."}, "cafeteria": {"available": true, "details": "Clean PM POSHAN kitchen and dining hall serving hot midday meals, eggs/chikki, and Ksheera Bhagya milk daily."}, "medical_room": {"available": true, "details": "Health checkup room with first aid supplies, regular visits by PHC medical officers under Rashtriya Bal Swasthya Karyakram (RBSK)."}, "internet": {"available": true, "speed": "100 Mbps BSNL BharatNet fiber connection."}, "accessibility": {"available": true, "features": ["Barrier-free entry ramps", "CWSN accessible toilet facilities", "Handrails on verandas"]}, "security": {"available": true, "features": ["Compound wall with gated security guard", "CCTV monitoring at campus gates and corridors"]}}','{"available": false, "boys_capacity": 0, "girls_capacity": 0, "food_details": "Day scholar institution. Free midday hot meals provided daily under PM POSHAN.", "amenities": [], "supervision": "Day scholar supervision by teachers and School Development and Monitoring Committee (SDMC).", "contact_phone": "+91-80-2334-1100"}','{"available": false, "fleet_size": 0, "gps_enabled": false, "routes": [], "transport_coordinator": "Located in central Malleshwaram within 200m of BMTC bus stop and Sampige Road Metro Station. Free BMTC bus passes provided to all enrolled students."}','{"academic_year": "2026-2027", "status": "Admissions Open for Classes 1 to 10", "eligibility_criteria": "Minimum age 6 years completed for Class 1 as of June 1. Open to all students without any screening or capitation fee as per RTE Act.", "process_steps": ["Step 1: Visit the school office or register on Karnataka SATS (Student Achievement Tracking System) portal.", "Step 2: Submit child''s birth certificate and address proof.", "Step 3: Verification of documents by Headmaster and instant admission entry in SATS.", "Step 4: Receive free textbooks, uniforms, and student ID card."], "scholarships": ["100% Free Tuition, Books, and School Uniforms (2 pairs per year).", "Government of Karnataka Pre-Matric Scholarships for SC/ST/OBC and minority pupils.", "Free bicycle scheme for rural students residing beyond 2 km."], "required_documents": ["Child''s Birth Certificate (Gram Panchayat / Municipal Corporation)", "Child''s Aadhaar Card copy", "Parents'' Aadhaar Card copies", "Caste and Income Certificate (for scholarship processing)", "Transfer Certificate (for admissions to Classes 2 through 10)"]}','Schools (K-10)',13.0076,77.5684);
INSERT INTO schools VALUES('SCH002','Shanti Vidya Mandir','Mysuru','Karnataka','School','KRS Road, Gokulam 3rd Stage, Mysuru, Karnataka 570002',1985,NULL,'+91-821-251-4455','https://www.shantividyamandir.edu.in','[]','https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Government_of_Karnataka_Logo.svg/300px-Government_of_Karnataka_Logo.svg.png','https://images.unsplash.com/photo-1580582932707-520aed937b7b?q=80&w=1200&auto=format&fit=crop','info@shantividyamandir.edu.in','Karnataka School Examination and Assessment Board (KSEAB)','Recognized by Department of School Education, Karnataka','Gokulam Campus',0,'https://maps.google.com/?q=Gokulam+Mysuru+School','{"introduction": "Shanti Vidya Mandir is a premier aided secondary institution in Mysuru, established in 1985. It emphasizes holistic character development, Sanskrit traditions, modern science education, and environmental ethics.", "history": "Founded by visionary educators in 1985, the school has consistently earned top academic distinctions in Mysuru district.", "vision": "Excellence in education blended with Indian cultural values and scientific temper.", "mission": ["Provide value-oriented education fostering character, compassion, and academic excellence.", "Nurture curiosity in science, arts, and languages.", "Promote physical fitness, yoga, and community service."], "educational_philosophy": "Holistic schooling integrating traditional Sanskrit and yoga wisdom with contemporary science and mathematics.", "teaching_methodology": "Interactive lectures, science experiments, storytelling, and yoga sessions.", "academic_environment": "Serene green environment in Gokulam with dedicated reading rooms and playground."}','{"classrooms": {"available": true, "count": 20, "description": "Well-lit classrooms with audio-visual equipment."}, "science_labs": {"available": true, "count": 2, "description": "Equipped physics, chemistry, and biology labs."}, "computer_labs": {"available": true, "count": 1, "description": "Computer room with 25 networked PCs."}, "library": {"available": true, "details": "Library with 6,000+ books in Kannada, English, and Sanskrit."}, "digital_learning": {"available": true, "details": "Smart class projectors for digital syllabus display."}, "sports": {"available": true, "details": "Playground for volleyball, badminton, kho-kho, and yoga hall."}, "auditorium": {"available": true, "count": 1, "details": "School auditorium seating 300 pupils."}, "cafeteria": {"available": true, "details": "Hygienic vegetarian dining area."}, "medical_room": {"available": true, "details": "First aid room with regular doctor visits."}, "internet": {"available": true, "speed": "50 Mbps fiber broadband."}, "accessibility": {"available": true, "features": ["Wheelchair ramp at entrance", "Ground floor accessible classrooms"]}, "security": {"available": true, "features": ["24/7 security watch", "CCTV monitoring"]}}','{"available": false, "boys_capacity": 0, "girls_capacity": 0, "food_details": "Day school.", "amenities": [], "supervision": "Day staff supervision.", "contact_phone": "+91-821-251-4455"}','{"available": true, "fleet_size": 4, "gps_enabled": true, "routes": [{"route_number": "Route 1", "origin": "Vijayanagar Mysuru", "stops": ["Hebbal", "Gokulam", "Campus"], "pickup_time": "08:00 AM"}, {"route_number": "Route 2", "origin": "Kuvempunagar", "stops": ["Saraswathipuram", "Campus"], "pickup_time": "08:10 AM"}], "transport_coordinator": "Transport Incharge, Phone: +91-821-251-4460"}','{"academic_year": "2026-2027", "status": "Admissions Open", "eligibility_criteria": "Admission to Classes 1-10 based on age and previous class performance.", "process_steps": ["Step 1: Obtain application from school office.", "Step 2: Submit with child''s birth certificate and previous marks card.", "Step 3: Verification and fee payment."], "scholarships": ["Merit-cum-means fee support from Shanti Vidya Trust.", "Government Pre-Matric scholarships."], "required_documents": ["Birth Certificate", "Aadhaar Card", "Previous School TC", "3 Passport Photos"]}','Schools (K-10)',12.3352,76.6341);
