INSERT INTO schools VALUES('COL001','Ramaiah Institute of Technology (MSRIT)','Bengaluru Urban','Karnataka','Degree College','MSR Nagar, Gnanagangothri Campus, Bengaluru, Karnataka 560054',1962,'Premier autonomous engineering institute affiliated to VTU, accredited by NBA and NAAC with ''A+'' grade. Ranked among top engineering colleges in India.','+91-80-2360-0822','https://www.msrit.edu','{"institution_category": "Engineering College", "affiliation": "Autonomous, Affiliated to Visvesvaraya Technological University (VTU)", "naac_grade": "A+ Grade (3.28 CGPA)", "nirf_rank": "#67 in Engineering (NIRF 2024)", "accreditation": "AICTE Approved, NBA Accredited Tier-1", "rating": "4.2 / 5 (468 Reviews)", "tuition_fees_range": "\u20b93.86 L - \u20b910.5 L", "median_package": "\u20b97.66 LPA", "highest_package": "\u20b950.0 LPA", "total_courses_count": 48, "top_recruiters": ["Amazon", "Cisco", "Adobe", "Infosys", "Wipro", "TCS", "Texas Instruments", "Capgemini", "Samsung R&D"], "campus_facilities": ["Boys & Girls Hostels", "Central Library (1.5L+ Books)", "High-Performance Computing Lab", "Gymnasium & Sports Complex", "Digital Smart Classrooms", "Campus-wide High Speed Wi-Fi", "Incubation Center (MSRIC)", "Apex Block Auditorium"], "admissions": {"accepted_exams": ["KCET", "COMEDK UGET", "Karnataka PGCET", "GATE", "MAT", "NATA"], "eligibility": "Passed 10+2 with Physics and Mathematics as compulsory subjects along with Chemistry/Biotech with min 45% aggregate (40% for SC/ST/OBC).", "application_process": "Admissions through KEA (KCET) government quota, COMEDK UGET state quota, and institutional merit quota."}, "courses": [{"course_id": "MSRIT-BE-CSE", "degree": "B.E. / B.Tech", "course_name": "B.E. in Computer Science and Engineering", "stream": "Engineering", "duration": "4 Years (8 Semesters)", "mode": "Full Time", "total_tuition_fee": "\u20b93,86,296", "seats": 180, "median_salary": "\u20b97.66 LPA", "eligibility": "10+2 with 45% in PCM + KCET / COMEDK UGET", "overview": 