INSERT INTO school_achievements VALUES('ACH_COL001_1','COL001','NIRF All India Engineering Rank 67','Ranked 67th across all Indian engineering institutions by the Ministry of Education, Government of India in NIRF 2023.',NULL,'https://www.nirfindia.org',1,2023,'National','Ministry of Education, GoI','verified');
INSERT INTO school_achievements VALUES('ACH_COL001_2','COL001','NAAC Accreditation with A+ Grade','Awarded institutional A+ Grade with a CGPA of 3.28 in Cycle 2 assessment by NAAC.',NULL,'http://www.naac.gov.in',1,2021,'National','National Assessment and Accreditation Council (NAAC)','verified');
INSERT INTO school_achievements VALUES('ACH_COL001_3','COL001','NBA Tier-1 Accreditation for 12 Programs','Accredited under Tier-1 Washington Accord for 12 UG Engineering branches by National Board of Accreditation.',NULL,'https://www.nbaind.org',1,2022,'National','National Board of Accreditation (NBA)','verified');
INSERT INTO school_achievements VALUES('ACH_COL001_4','COL001','Smart India Hackathon 1st Prize Winner','Student innovation team won 1st prize in the Hardware Edition of Smart India Hackathon conducted by AICTE and MoE.',NULL,'https://sih.gov.in',1,2023,'National','AICTE & Ministry of Education','verified');
INSERT INTO school_achievements VALUES('ACH_COL002_1','COL002','NIRF All India Engineering Rank 89','Consistently ranked among the top 100 engineering institutions nationwide in NIRF rankings.',NULL,'https://www.nirfindia.org',1,2023,'National','Ministry of Education, GoI','verified');
INSERT INTO school_achievements VALUES('ACH_COL002_2','COL002','NAAC A+ Accreditation','Awarded prestigious A+ accreditation by the National Assessment and Accreditation Council.',NULL,'http://www.naac.gov.in',1,2022,'National','NAAC','verified');
INSERT INTO school_achievements VALUES('ACH_COL002_3','COL002','Formula Bharat Champions Trophy','Team Ashwa Racing won overall 1st position in Formula Bharat National Engineering Design Competition.',NULL,'https://www.formulabharat.com',1,2023,'National','Formula Bharat & SAE India','verified');
INSERT INTO school_achievements VALUES('ACH_COL003_1','COL003','NAAC Accreditation with A++ Grade (CGPA 3.83)','Awarded highest institutional A++ accreditation grade with 3.83 CGPA on a 4-point scale by NAAC.',NULL,'http://www.naac.gov.in',1,2023,'National','National Assessment and Accreditation Council (NAAC)','verified');
INSERT INTO school_achievements VALUES('ACH_COL003_2','COL003','NIRF Engineering Top 100 Ranking','Secured top tier ranking in NIRF National Institutional Ranking Framework.',NULL,'https://www.nirfindia.org',1,2023,'National','Ministry of Education, GoI','verified');
INSERT INTO school_achievements VALUES('ACH_COL004_1','COL004','PISAT Student Nano-Satellite Launch by ISRO','PISAT designed and developed by PES University students successfully placed into orbit by ISRO PSLV-C35.',NULL,'https://www.isro.gov.in',1,2021,'National','Indian Space Research Organisation (ISRO)','verified');
INSERT INTO school_achievements VALUES('ACH_COL004_2','COL004','NAAC A+ Accreditation','Accredited with A+ grade by National Assessment and Accreditation Council.',NULL,'http://www.naac.gov.in',1,2022,'National','NAAC','verified');
INSERT INTO school_achievements VALUES('ACH_COL006_1','COL006','NAAC A++ Accreditation (CGPA 3.79)','Attained premier A++ accreditation rating from NAAC in the 4th cycle evaluation.',NULL,'http://www.naac.gov.in',1,2022,'National','NAAC','verified');
INSERT INTO school_achievements VALUES('ACH_COL006_2','COL006','College with Potential for Excellence (CPE)','Recognized as a College of Excellence by the University Grants Commission.',NULL,'https://www.ugc.gov.in',1,2020,'National','University Grants Commission (UGC)','verified');
INSERT INTO school_achievements VALUES('ACH_COL007_1','COL007','NAAC A+ Grade Cycle 4','Secured A+ grade institutional rating in fourth accreditation cycle.',NULL,'http://www.naac.gov.in',1,2021,'National','NAAC','verified');
INSERT INTO school_achievements VALUES('ACH_COL009_1','COL009','NAAC A++ Accreditation (CGPA 3.82)','Achieved prestigious A++ grade in 4th assessment cycle recognizing over a century of research excellence.',NULL,'http://www.naac.gov.in',1,2023,'National','National Assessment and Accreditation Council','verified');
INSERT INTO school_achievements VALUES('ACH_COL009_2','COL009','University with Potential for Excellence (UPE)','Conferred Institution of Excellence status with grant support by UGC.',NULL,'https://www.ugc.gov.in',1,2020,'National','UGC, New Delhi','verified');
INSERT INTO school_achievements VALUES('ACH_SCH001_1','SCH001','PM SHRI School Designation','Selected under the prestigious Pradhan Mantri Schools for Rising India (PM SHRI) initiative for exemplary digital and pedagogical infrastructure.',NULL,'https://pmshrischools.education.gov.in',1,2023,'National','Ministry of Education, GoI','verified');
INSERT INTO school_achievements VALUES('ACH_SCH001_2','SCH001','100% SSLC Examination Pass Distinction','Achieved 100% pass percentage in Karnataka State SSLC Board Examination with 18 student distinctions.',NULL,'https://kseab.karnataka.gov.in',1,2023,'State','Karnataka School Examination and Assessment Board (KSEAB)','verified');
INSERT INTO school_achievements VALUES('ACH_SCH001_3','SCH001','State Level Science Fair 1st Prize','Primary student innovators secured 1st place in the Karnataka State Children''s Science Congress for Eco-Water Harvesting.',NULL,'https://schooleducation.karnataka.gov.in',1,2022,'State','Department of School Education, Karnataka','verified');
INSERT INTO school_achievements VALUES('ACH_SCH002_1','SCH002','Pratibha Karanji Mysuru District Champions','Secured District Championship in Pratibha Karanji state cultural youth competition in folk song and drama.',NULL,'https://schooleducation.karnataka.gov.in',1,2023,'District','Dept of School Education Mysuru','verified');
